import React, { useEffect, useState } from 'react';
import Create from './Create';
import api from './api';
import { BsCircle, BsFillCheckCircleFill, BsFillTrashFill, BsPencil, BsCheckLg } from 'react-icons/bs';

const styles = `
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

  body {
    margin: 0;
    min-height: 100vh;
    font-family: 'Inter', system-ui, sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    background-attachment: fixed;
  }

  .todo-app {
    max-width: 560px;
    margin: 0 auto;
    padding: 56px 20px 40px;
  }

  .todo-header {
    text-align: center;
    color: #fff;
    margin-bottom: 28px;
  }
  .todo-header h1 {
    margin: 0;
    font-size: 2.4rem;
    font-weight: 700;
    letter-spacing: -0.5px;
  }
  .todo-header p {
    margin: 6px 0 0;
    opacity: 0.85;
    font-size: 0.95rem;
  }

  .todo-card {
    background: rgba(255, 255, 255, 0.95);
    border-radius: 20px;
    padding: 24px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.2);
  }

  /* Styles the Create component's form (input + button) */
  .create-wrap {
    margin-bottom: 20px;
  }
  .create-wrap form,
  .create-wrap > div {
    display: flex;
    gap: 10px;
  }
  .create-wrap input {
    flex: 1;
    padding: 13px 16px;
    border: 2px solid #e5e7eb;
    border-radius: 12px;
    font-size: 1rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.2s, box-shadow 0.2s;
  }
  .create-wrap input:focus {
    border-color: #764ba2;
    box-shadow: 0 0 0 4px rgba(118, 75, 162, 0.15);
  }
  .create-wrap button {
    padding: 0 22px;
    border: none;
    border-radius: 12px;
    background: linear-gradient(135deg, #667eea, #764ba2);
    color: #fff;
    font-weight: 600;
    font-size: 0.95rem;
    font-family: inherit;
    cursor: pointer;
    transition: transform 0.15s, box-shadow 0.15s;
  }
  .create-wrap button:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(118, 75, 162, 0.4);
  }
  .create-wrap button:active {
    transform: translateY(0);
  }

  .todo-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .todo-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 16px;
    background: #fff;
    border: 1px solid #eef0f4;
    border-radius: 14px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
    transition: transform 0.2s, box-shadow 0.2s;
    animation: slideIn 0.3s ease;
  }
  .todo-item:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
  }

  @keyframes slideIn {
    from { opacity: 0; transform: translateY(8px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  .todo-left {
    display: flex;
    align-items: center;
    gap: 14px;
    flex: 1;
    min-width: 0;
  }

  .todo-check {
    font-size: 1.35rem;
    flex-shrink: 0;
    color: #c4c9d4;
    cursor: pointer;
    transition: color 0.2s, transform 0.2s;
  }
  .todo-check:hover {
    color: #764ba2;
    transform: scale(1.15);
  }
  .todo-check.done {
    color: #22c55e;
    cursor: default;
  }
  .todo-check.done:hover {
    transform: none;
  }

  .todo-text {
    margin: 0;
    font-size: 1rem;
    color: #1f2937;
    word-break: break-word;
    transition: color 0.2s;
  }
  .todo-text.done {
    text-decoration: line-through;
    color: #9ca3af;
  }

  .todo-edit-input {
    flex: 1;
    min-width: 0;
    padding: 8px 12px;
    border: 2px solid #764ba2;
    border-radius: 8px;
    font-size: 1rem;
    font-family: inherit;
    outline: none;
    box-shadow: 0 0 0 4px rgba(118, 75, 162, 0.12);
  }

  .todo-actions {
    display: flex;
    gap: 6px;
    flex-shrink: 0;
  }
  .todo-btn {
    display: grid;
    place-items: center;
    width: 36px;
    height: 36px;
    border: none;
    border-radius: 10px;
    background: #f3f4f6;
    color: #6b7280;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.2s, color 0.2s, transform 0.15s;
  }
  .todo-btn:hover { transform: scale(1.08); }
  .todo-btn.edit:hover   { background: #ede9fe; color: #7c3aed; }
  .todo-btn.save         { background: #dcfce7; color: #16a34a; }
  .todo-btn.save:hover   { background: #bbf7d0; }
  .todo-btn.delete:hover { background: #fee2e2; color: #dc2626; }

  .todo-empty {
    text-align: center;
    padding: 36px 16px;
    color: #9ca3af;
    font-size: 1rem;
  }
  .todo-empty span {
    display: block;
    font-size: 2.2rem;
    margin-bottom: 8px;
  }

  @media (max-width: 480px) {
    .todo-app { padding-top: 36px; }
    .todo-header h1 { font-size: 1.9rem; }
    .todo-card { padding: 16px; border-radius: 16px; }
  }
`;

const Home = () => {
    const [todos, setTodos] = useState([]);
    const [updatetask, setUpdatetask] = useState('');
    const [taskid, setTaskid] = useState('');

    useEffect(() => {
        api.get('/get')
            .then(result => setTodos(result.data))
            .catch(err => console.log(err));
    }, []);

    const edit = (id) => {
        api.put(`/edit/${id}`)
            .then(result => {
                console.log(result.data);
                setTodos(todos.map(todo =>
                    todo._id === id ? { ...todo, done: !todo.done } : todo
                ));
            })
            .catch(err => console.log(err));
    };

    const Update = (id, updatedTask) => {
        api.put(`/update/${id}`, { task: updatedTask })
            .then(result => {
                console.log(result.data);
                setTodos(todos.map(todo =>
                    todo._id === id ? { ...todo, task: updatedTask } : todo
                ));
                setTaskid('');
                setUpdatetask('');
            })
            .catch(err => console.log(err));
    };

    const Hdelete = (id) => {
        api.delete(`/delete/${id}`)
            .then(result => {
                console.log(result.data);
                setTodos(todos.filter(todo => todo._id !== id));
            })
            .catch(err => console.log(err));
    };

    const remaining = todos.filter(t => !t.done).length;

    return (
        <main className='todo-app'>
            <style>{styles}</style>

            <header className='todo-header'>
                <h1>My Tasks</h1>
                <p>
                    {todos.length === 0
                        ? 'Nothing on your list yet'
                        : `${remaining} of ${todos.length} remaining`}
                </p>
            </header>

            <div className='todo-card'>
                <div className='create-wrap'>
                    <Create />
                </div>

                {todos.length === 0 ? (
                    <div className='todo-empty'>
                        <span>📝</span>
                        No tasks found
                    </div>
                ) : (
                    <div className='todo-list'>
                        {todos.map((todo) => (
                            <div className='todo-item' key={todo._id}>
                                <div className='todo-left'>
                                    {todo.done
                                        ? <BsFillCheckCircleFill className='todo-check done' />
                                        : <BsCircle className='todo-check' onClick={() => edit(todo._id)} />}

                                    {taskid === todo._id ? (
                                        <input
                                            className='todo-edit-input'
                                            type='text'
                                            autoFocus
                                            value={updatetask}
                                            onChange={e => setUpdatetask(e.target.value)}
                                            onKeyDown={e => {
                                                if (e.key === 'Enter') Update(todo._id, updatetask);
                                                if (e.key === 'Escape') { setTaskid(''); setUpdatetask(''); }
                                            }}
                                        />
                                    ) : (
                                        <p className={`todo-text ${todo.done ? 'done' : ''}`}>{todo.task}</p>
                                    )}
                                </div>

                                <div className='todo-actions'>
                                    <button
                                        className={`todo-btn ${taskid === todo._id ? 'save' : 'edit'}`}
                                        title={taskid === todo._id ? 'Save' : 'Edit'}
                                        onClick={() => {
                                            if (taskid === todo._id) {
                                                Update(todo._id, updatetask);
                                            } else {
                                                setTaskid(todo._id);
                                                setUpdatetask(todo.task);
                                            }
                                        }}
                                    >
                                        {taskid === todo._id ? <BsCheckLg /> : <BsPencil />}
                                    </button>
                                    <button
                                        className='todo-btn delete'
                                        title='Delete'
                                        onClick={() => Hdelete(todo._id)}
                                    >
                                        <BsFillTrashFill />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </main>
    );
};

export default Home;
